<?php
namespace Opencart\Admin\Model\Extension\Linnworks\Module;
class Linnworks extends \Opencart\System\Engine\Model {
 public function install():void{foreach(["CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_account` (`account_id` int NOT NULL AUTO_INCREMENT,`sid_registration` varchar(36) NOT NULL DEFAULT '',`account_name` varchar(128) NOT NULL DEFAULT '',`email` varchar(255) NOT NULL DEFAULT '',`authorization_token_hash` varchar(255) NOT NULL DEFAULT '',`status` tinyint(1) NOT NULL DEFAULT 1,`date_added` datetime NOT NULL,`date_modified` datetime NOT NULL,PRIMARY KEY(`account_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_mapping` (`mapping_id` int NOT NULL AUTO_INCREMENT,`product_id` int NOT NULL,`stock_item_id` varchar(36) NOT NULL DEFAULT '',`ean` varchar(64) NOT NULL DEFAULT '',`model` varchar(64) NOT NULL DEFAULT '',`sku` varchar(64) NOT NULL DEFAULT '',`status` varchar(32) NOT NULL DEFAULT 'pending',`date_added` datetime NOT NULL,`date_modified` datetime NOT NULL,PRIMARY KEY(`mapping_id`),UNIQUE KEY `product_id`(`product_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_queue` (`queue_id` bigint NOT NULL AUTO_INCREMENT,`job_type` varchar(64) NOT NULL,`entity_id` varchar(64) NOT NULL,`payload` mediumtext,`status` varchar(24) NOT NULL DEFAULT 'pending',`attempts` int NOT NULL DEFAULT 0,`date_added` datetime NOT NULL,`date_modified` datetime NOT NULL,PRIMARY KEY(`queue_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_log` (`log_id` bigint NOT NULL AUTO_INCREMENT,`level` varchar(16) NOT NULL,`area` varchar(32) NOT NULL,`message` text NOT NULL,`context` mediumtext,`date_added` datetime NOT NULL,PRIMARY KEY(`log_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_scan` (`scan_id` bigint NOT NULL AUTO_INCREMENT,`started_at` datetime NOT NULL,`completed_at` datetime NULL,`status` varchar(24) NOT NULL,`identifier_code` varchar(64) NOT NULL,`products_scanned` int NOT NULL DEFAULT 0,`ready_count` int NOT NULL DEFAULT 0,`warning_count` int NOT NULL DEFAULT 0,`critical_count` int NOT NULL DEFAULT 0,`health_score` decimal(5,2) NOT NULL DEFAULT 0,PRIMARY KEY(`scan_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_scan_product` (`scan_product_id` bigint NOT NULL AUTO_INCREMENT,`scan_id` bigint NOT NULL,`product_id` int NOT NULL,`name` varchar(255) NOT NULL DEFAULT '',`model` varchar(255) NOT NULL DEFAULT '',`normalised_model` varchar(255) NOT NULL DEFAULT '',`identifier_value` varchar(255) NOT NULL DEFAULT '',`price` decimal(15,4) NOT NULL DEFAULT 0,`quantity` int NOT NULL DEFAULT 0,`readiness_score` int NOT NULL DEFAULT 0,`ready_for_sync` tinyint(1) NOT NULL DEFAULT 0,PRIMARY KEY(`scan_product_id`),UNIQUE KEY(`scan_id`,`product_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","CREATE TABLE IF NOT EXISTS `".DB_PREFIX."linnworks_scan_issue` (`issue_id` bigint NOT NULL AUTO_INCREMENT,`scan_id` bigint NOT NULL,`product_id` int NULL,`severity` varchar(16) NOT NULL,`category` varchar(32) NOT NULL,`description` text NOT NULL,`recommendation` text NULL,`date_added` datetime NOT NULL,PRIMARY KEY(`issue_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"] as $q)$this->db->query($q);}
 public function authorize(array $s):array{return $this->request('POST',$s['auth_url'],['ApplicationId'=>trim($s['application_id']),'ApplicationSecret'=>trim($s['application_secret']),'Token'=>trim($s['token'])],'',(int)$s['timeout']);}
 public function locations(array $s):array{$a=$this->authorize($s);$server=rtrim((string)($a['Server']??''),'/');$token=(string)($a['Token']??'');if(!$server||!$token)throw new \RuntimeException('Authentication did not return Server and Token.');return $this->request('GET',$server.'/api/Inventory/GetStockLocations',null,$token,(int)$s['timeout']);}
 public function scan(string $code='EAN'):array{$this->install();$code=strtoupper(trim($code));$this->db->query("INSERT INTO `".DB_PREFIX."linnworks_scan` SET started_at=NOW(),status='running',identifier_code='".$this->db->escape($code)."'");$id=(int)$this->db->getLastId();$lang=(int)$this->config->get('config_language_id');$dups=[];$dq=$this->db->query("SELECT TRIM(value) v,COUNT(DISTINCT product_id) c FROM `".DB_PREFIX."product_code` WHERE UPPER(code)='".$this->db->escape($code)."' AND TRIM(value)<>'' GROUP BY TRIM(value) HAVING c>1");foreach($dq->rows as $d)$dups[$d['v']]=1;$q=$this->db->query("SELECT p.product_id,p.model,p.price,p.quantity,p.status,COALESCE(pd.name,'') name,COALESCE(MAX(CASE WHEN UPPER(pc.code)='".$this->db->escape($code)."' THEN TRIM(pc.value) END),'') ident FROM `".DB_PREFIX."product` p LEFT JOIN `".DB_PREFIX."product_description` pd ON pd.product_id=p.product_id AND pd.language_id=$lang LEFT JOIN `".DB_PREFIX."product_code` pc ON pc.product_id=p.product_id GROUP BY p.product_id,p.model,p.price,p.quantity,p.status,pd.name");$ready=$warn=$crit=0;foreach($q->rows as $r){$issues=[];$ident=trim($r['ident']);$model=trim($r['model']);if($ident==='')$issues[]=['warning','identifier','No '.$code.' exists for this product.','Add the identifier or review the model fallback.'];elseif(isset($dups[$ident]))$issues[]=['critical','identifier','Duplicate '.$code.' found.','Correct the duplicate before automatic matching.'];elseif(!ctype_digit($ident)||!in_array(strlen($ident),[8,12,13,14],true))$issues[]=['warning','identifier','Invalid barcode format.','Check the product-code value.'];if($model==='')$issues[]=['warning','model','The product model is blank.','Add a model for fallback matching.'];if((float)$r['price']<0)$issues[]=['critical','price','The product price is negative.','Correct the product price.'];elseif((float)$r['price']==0)$issues[]=['warning','price','The product price is zero.','Confirm the intended price.'];if((int)$r['quantity']<0)$issues[]=['critical','stock','The product quantity is negative.','Correct the stock quantity.'];if(!(int)$r['status'])$issues[]=['info','status','The product is disabled.','No action required unless it should synchronise.'];$score=100;$hasCrit=false;foreach($issues as $x){if($x[0]==='critical'){$crit++;$score-=35;$hasCrit=true;}elseif($x[0]==='warning'){$warn++;$score-=10;}$this->db->query("INSERT INTO `".DB_PREFIX."linnworks_scan_issue` SET scan_id=$id,product_id=".(int)$r['product_id'].",severity='".$x[0]."',category='".$x[1]."',description='".$this->db->escape($x[2])."',recommendation='".$this->db->escape($x[3])."',date_added=NOW()");}$isReady=($ident!==''&&!isset($dups[$ident])&&!$hasCrit);if($isReady)$ready++;$norm=preg_replace('/^N(?=\d)/','',preg_replace('/[\s\-_]+/','',strtoupper($model)));$this->db->query("INSERT INTO `".DB_PREFIX."linnworks_scan_product` SET scan_id=$id,product_id=".(int)$r['product_id'].",name='".$this->db->escape($r['name'])."',model='".$this->db->escape($model)."',normalised_model='".$this->db->escape($norm)."',identifier_value='".$this->db->escape($ident)."',price=".(float)$r['price'].",quantity=".(int)$r['quantity'].",readiness_score=".max(0,$score).",ready_for_sync=".(int)$isReady);}$total=count($q->rows);$health=$total?round($ready/$total*100,2):0;$this->db->query("UPDATE `".DB_PREFIX."linnworks_scan` SET completed_at=NOW(),status='completed',products_scanned=$total,ready_count=$ready,warning_count=$warn,critical_count=$crit,health_score=$health WHERE scan_id=$id");return $this->scanSummary($id);}
 public function dashboard():array{return $this->scanSummary(0)?:['products_scanned'=>0,'ready_count'=>0,'warning_count'=>0,'critical_count'=>0,'health_score'=>0,'identifier_coverage'=>0];}
 public function scanSummary(int $id=0):array{$this->install();$w=$id?' WHERE scan_id='.(int)$id:'';$q=$this->db->query("SELECT * FROM `".DB_PREFIX."linnworks_scan`$w ORDER BY scan_id DESC LIMIT 1");if(!$q->num_rows)return [];$r=$q->row;$c=$this->db->query("SELECT COUNT(*) t,SUM(identifier_value<>'') c FROM `".DB_PREFIX."linnworks_scan_product` WHERE scan_id=".(int)$r['scan_id'])->row;$r['identifier_coverage']=$c['t']?round($c['c']/$c['t']*100,1):0;return $r;}
 public function scanHistory(int $l=20):array{$this->install();return $this->db->query("SELECT * FROM `".DB_PREFIX."linnworks_scan` ORDER BY scan_id DESC LIMIT ".(int)$l)->rows;}
 public function scanProducts(array $f=[]):array{$id=(int)($f['scan_id']??0);if(!$id)$id=(int)($this->scanSummary()['scan_id']??0);$w=["scan_id=$id"];if(($f['ready']??'')!=='')$w[]='ready_for_sync='.(int)$f['ready'];if(!empty($f['search'])){$s=$this->db->escape($f['search']);$w[]="(name LIKE '%$s%' OR model LIKE '%$s%' OR identifier_value LIKE '%$s%')";}return $this->db->query("SELECT * FROM `".DB_PREFIX."linnworks_scan_product` WHERE ".implode(' AND ',$w)." ORDER BY ready_for_sync,readiness_score,product_id LIMIT ".(int)($f['limit']??100))->rows;}
 public function issues(array $f=[]):array{$id=(int)($f['scan_id']??0);if(!$id)$id=(int)($this->scanSummary()['scan_id']??0);$w=["i.scan_id=$id"];if(!empty($f['severity']))$w[]="i.severity='".$this->db->escape($f['severity'])."'";if(!empty($f['category']))$w[]="i.category='".$this->db->escape($f['category'])."'";return $this->db->query("SELECT i.*,p.name,p.model,p.identifier_value FROM `".DB_PREFIX."linnworks_scan_issue` i LEFT JOIN `".DB_PREFIX."linnworks_scan_product` p ON p.scan_id=i.scan_id AND p.product_id=i.product_id WHERE ".implode(' AND ',$w)." ORDER BY FIELD(i.severity,'critical','warning','info'),i.issue_id LIMIT ".(int)($f['limit']??100))->rows;}
 public function codeTypes():array{return $this->db->query("SELECT UPPER(code) code,COUNT(*) total FROM `".DB_PREFIX."product_code` GROUP BY UPPER(code) ORDER BY code")->rows;}
 private function request(string $m,string $u,?array $p,string $t,int $to):array{if(!function_exists('curl_init'))throw new \RuntimeException('PHP cURL is not installed.');$c=curl_init($u);$h=['Accept: application/json','Content-Type: application/json'];if($t)$h[]='Authorization: '.$t;$o=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$h,CURLOPT_CONNECTTIMEOUT=>$to,CURLOPT_TIMEOUT=>$to,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2];if($m==='POST'){$o[CURLOPT_POST]=true;$o[CURLOPT_POSTFIELDS]=json_encode($p??[]);}curl_setopt_array($c,$o);$b=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);$e=curl_error($c);curl_close($c);if($b===false||$e)throw new \RuntimeException('HTTPS request failed: '.$e);$j=json_decode($b,true);if($code<200||$code>=300)throw new \RuntimeException('Linnworks HTTP '.$code.': '.substr((string)($j['Message']??$j['message']??$b),0,500));if(!is_array($j))throw new \RuntimeException('Linnworks returned invalid JSON.');return $j;}
}
